window.products.push({"id":1229044,"name":"Confetti Initial Bag Charm - Multi — A","category":"jewelry","retail price":24.0,"sale price":null,"image":"https://cdn.shopify.com/s/files/1/0267/5746/4148/files/125264_G_A_RS_SQ_2026_10e4a2ef-3227-4059-b080-24db4cce2ef9.jpg?v=1784196430","description":"Add some vibrant hues to your purse with the Confetti Initial Bag Charm. Featuring the letter of your choosing in a bold, bubble-letter font, this bold Bag Charm is embellished with dainty multicolored stones for added sparkle. Treat yourself to an bag charm that will bring a pop of color to any bag! Enhance your bag with our stylish Bag Charms crafted from premium materials. Please consider your bag's material to prevent potential surface impact. Enjoy accessorizing without worry!","images":["https://cdn.shopify.com/s/files/1/0267/5746/4148/files/125264_G_A_RS_SQ_2026_10e4a2ef-3227-4059-b080-24db4cce2ef9.jpg?v=1784196430","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174620_SS_01_SQ.jpg?v=1786566813","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174624_SS_01_SQ.jpg?v=1786566844","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174623_SS_01_SQ.jpg?v=1786566838","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174622_SS_01_SQ.jpg?v=1786566830","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174621_SS_01_SQ.jpg?v=1786566824"],"specifications":{"brand":"BaubleBar","product_type":"Bag Charms","source_store":"baublebar.com","source_variant_id":"41538105737300"},"sku":"BM-1229044","productType":"Jewelry","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://baublebar.com/products/confetti-initial-bag-charm","source_catalog":"Public Shopify online-store product feed","source_store":"baublebar.com","source_handle":"confetti-initial-bag-charm","source_variant_id":"41538105737300","price_pending":true,"merchant_ready":false});
